import java.io.*; import java.util.*; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; StringTokenizer st = new StringTokenizer(line); int n = Integer.parseInt(st.nextToken()); long x = Long.parseLong(st.nextToken()); long[] v = new long[n + 1]; st = new StringTokenizer(br.readLine()); for (int i = 1; i <= n; i++) v[i] = Long.parseLong(st.nextToken()); List<Integer>[] adj = new ArrayList[n + 1]; for (int i = 1; i <= n; i++) adj[i] = new ArrayList<Integer>(); for (int i = 0; i < n - 1; i++) { st = new StringTokenizer(br.readLine()); int u = Integer.parseInt(st.nextToken()); int v_node = Integer.parseInt(st.nextToken()); adj[u].add(v_node); adj[v_node].add(u); } int[] parent = new int[n + 1]; int[] depth = new int[n + 1]; int[] childrenCount = new int[n + 1]; Queue<Integer> q = new LinkedList<Integer>(); q.add(1); depth[1] = 1; boolean[] visited = new boolean[n + 1]; visited[1] = true; List<Integer> order = new ArrayList<Integer>(); while (!q.isEmpty()) { int curr = q.poll(); order.add(curr); for (int neighbor : adj[curr]) { if (!visited[neighbor]) { visited[neighbor] = true; parent[neighbor] = curr; childrenCount[curr]++; depth[neighbor] = depth[curr] + 1; q.add(neighbor); } } } int minDepth = Integer.MAX_VALUE; for (int i = 1; i <= n; i++) { if (childrenCount[i] < 2) { if (depth[i] < minDepth) { minDepth = depth[i]; } } } long[] subtreeSum = new long[n + 1]; for (int i = n - 1; i >= 0; i--) { int curr = order.get(i); subtreeSum[curr] += v[curr]; if (parent[curr] != 0) { subtreeSum[parent[curr]] += subtreeSum[curr]; } } long totalSum = 0; for (int i = 1; i <= n; i++) totalSum += subtreeSum[i]; totalSum += (long)(minDepth + 1) * x; System.out.println(totalSum); } }